{
  "decision": "accept",
  "icd10_code": "E11.22",
  "code_display": "Type 2 DM with diabetic CKD",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "The classification presumes a causal relationship between the two conditions linked by these terms in the Alphabetic Index or Tabular List. These conditions should be coded as related even in the absence of provider documentation explicitly linking them, unless the documentation clearly states the conditions are unrelated or when another guideline exists that specifically requires a documented linkage between two conditions (e.g., sepsis guideline for “acute organ dysfunction that is not clearly associated with the sepsis”).",
      "source": "ICD-10-CM Official Guidelines for Coding and Reporting FY 2027, Section I.A.15, page 11"
    }
  ],
  "rationale": "The chart documents active Type 2 diabetes mellitus (Assessment: type 2 diabetes mellitus with hyperglycemia, currently active; HbA1c 8.2%) and active chronic kidney disease stage 3 (Chronic kidney disease stage 3 is active). Per ICD-10-CM guidelines (FY2027, I.A.15), a causal relationship is presumed between diabetes and CKD for combination code E11.22 even without explicit provider documentation linking them, unless documentation states they are unrelated. No negation, family history, screening, hypothetical, or resolved language appears. The combination code is therefore supported.",
  "physician_query_needed": false
}
